$$\mathbf{x}_{k + 1} = \begin{bmatrix}
      y_{k + 1} \\
      y_{k + 2} \\
      y_{k + 3}
      \end{bmatrix} = \begin{bmatrix}
      {~ \mspace{-4mu} 0} & + & {~{\,\,\,\mspace{-4mu}\mspace{-4mu}\,y_{k + 1}}} & + & 0 \\
      { \mspace{-4mu}~0} & + & 0 & + & {\,\,~y_{k + 2}} \\
      {- 6y_{k}} & + & {5y_{k + 1}} & + & {2y_{k + 2}}
      \end{bmatrix} = \left\lbrack \begin{array}{rrr}
      0 & 1 & 0 \\
      0 & 0 & 1 \\
      {- 6} & 5 & 2
      \end{array} \right\rbrack\left\lbrack \begin{array}{l}
      y_{k} \\
      y_{k + 1} \\
      y_{k + 2}
      \end{array} \right\rbrack$$

$$\mathbf{x}_{k} = \begin{bmatrix}
      y_{k} \\
      y_{k + 1} \\
       \vdots \\
      y_{k\,\,\, + \,\,\,n - 1}
      \end{bmatrix}\,\text{,\quad}A = \begin{bmatrix}
      0 & 1 & 0 & \ldots & 0 \\
      0 & 0 & 1 & & 0 \\
       \vdots & & & \ddots & \vdots \\
      0 & 0 & 0 & & 1 \\
      {- a_{n}} & {- a_{n - 1}} & {- a_{n - 2}} & \cdots & {- a_{1}}
      \end{bmatrix}$$

